import type { Mm } from '../model/types.js';

/**
 * Where each theme's title page puts its lines — MEASURED, do not hand-edit.
 *
 * Generated by the procedure in `tools/theme-colours.md`: a `\titlepage` is compiled per
 * theme with known sample text, and each line's baseline, font size and horizontal
 * anchor come out of the PDF's text layer.
 *
 * The canvas used to draw `\titlepage` as a grey box containing the literal characters
 * `\titlepage`, which resembled the compiled slide not at all. Twenty-eight of the 35
 * themes do share beamer's default layout, but the ones that do not are not close:
 * metropolis and moloch are left-aligned at the text margin and reorder the credits,
 * Nord sets its title at 24.8pt and runs author and institute onto one line, Cuerna puts
 * the author at the FOOT of the page, and the sidebar themes centre on their text area
 * rather than on the page.
 *
 * FORMAT. `align|anchor|line|line|...`, where `align` is `c` or `l`, `anchor` is the
 * block's centre in millimetres when centred and its left edge when not, and each line
 * is `baselineMm:sizePt:field[+field...]`. Fields sharing a baseline are set on one line
 * by beamer and are rendered on one line here.
 *
 * NOT captured: decorations with no field of their own — Bergen's "Who? / From? / When?"
 * labels and Nord's "by" and "on". They are part of those themes' title pages and the
 * canvas simply omits them.
 */

export type TitleField = 'title' | 'subtitle' | 'author' | 'institute' | 'date';

export interface TitleLine {
  /** Millimetres from the top of the page to this line's baseline. */
  baselineMm: Mm;
  /** Font size in points, as the engine set it. */
  sizePt: number;
  /** The fields on this line, in the order beamer sets them. */
  fields: readonly TitleField[];
}

export interface TitleLayout {
  align: 'center' | 'left';
  /** The block's centre when centred, its left edge when left-aligned. */
  anchorMm: Mm;
  lines: readonly TitleLine[];
}

