function decode(row: string): TitleLayout {
  const [align, anchor, ...lines] = row.split('|');
  return {
    align: align === 'l' ? 'left' : 'center',
    anchorMm: Number(anchor),
    lines: lines.map((l) => {
      const [baseline, size, fields] = l.split(':');
      return {
        baselineMm: Number(baseline),
        sizePt: Number(size),
        fields: (fields ?? '').split('+') as TitleField[],
      };
    }),
  };
}

export const TITLE_LAYOUTS: Readonly<Record<string, TitleLayout>> =
  Object.fromEntries(Object.entries(RAW).map(([k, v]) => [k, decode(v)]));

/**
 * Beamer's own layout, used for a theme that was never measured.
 *
 * Twenty-eight of the 35 measured themes agree with it to within a millimetre, so it is
 * the right thing to fall back to.
 */
export const DEFAULT_TITLE_LAYOUT: TitleLayout = TITLE_LAYOUTS['default']!;

export function titleLayoutFor(theme: string): TitleLayout {
  return TITLE_LAYOUTS[theme] ?? DEFAULT_TITLE_LAYOUT;
}
